// 1. 获取请求参数
const request = $('When Executed by Another Workflow').first().json;

const orderId = String(request.order_id ?? '').trim();
const email = String(request.customer_email ?? '').trim().toLowerCase();

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.order_id);

// 2. 请求参数校验
if (!orderId || !email) {
  return [{
    json: {
      success: false,
      status: 'MISSING_PARAMETERS',
      message: 'Order ID and customer email are required.'
    }
  }];
}

// 3. 匹配订单号和客户邮箱
const order = rows.find(row =>
  String(row.order_id).trim() === orderId &&
  String(row.customer_email ?? '').trim().toLowerCase() === email
);

if (!order) {
  return [{
    json: {
      success: false,
      status: 'NOT_FOUND',
      message: 'No matching order was found.'
    }
  }];
}

// 4. 获取英国业务时区的当前日期
const currentDate = $now
  .setZone('Europe/London')
  .toISODate();

// 5. 标准化订单状态和预计送达日期
const orderStatus = String(order.status ?? '')
  .trim()
  .toLowerCase();

const estimatedDelivery = String(
  order.estimated_delivery ?? ''
).trim();

// 将 YYYY-MM-DD 转换为 UTC 日期时间戳
// 避免时区和夏令时影响自然日计算
function parseDate(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return null;
  }

  const timestamp = Date.parse(value + 'T00:00:00Z');

  if (!Number.isFinite(timestamp)) {
    return null;
  }

  if (new Date(timestamp).toISOString().slice(0, 10) !== value) {
    return null;
  }

  return timestamp;
}

const todayTimestamp = parseDate(currentDate);
const estimatedTimestamp = parseDate(estimatedDelivery);

// 6. 确定性业务规则：配送状态与逾期天数
let deliveryStatus = 'UNKNOWN';
let daysOverdue = null;

if (orderStatus === 'delivered') {

  deliveryStatus = 'DELIVERED';

} else if (orderStatus === 'cancelled') {

  deliveryStatus = 'CANCELLED';

} else if (
  ['shipped', 'processing'].includes(orderStatus) &&
  estimatedTimestamp !== null &&
  todayTimestamp !== null
) {

  const daysDifference = Math.round(
    (todayTimestamp - estimatedTimestamp) / 86400000
  );

  daysOverdue = Math.max(0, daysDifference);

  if (daysOverdue > 0) {
    deliveryStatus = 'OVERDUE';
  } else if (orderStatus === 'shipped') {
    deliveryStatus = 'IN_TRANSIT';
  } else {
    deliveryStatus = 'PENDING';
  }

}

// 7. 返回结构化订单信息
return [{
  json: {
    success: true,
    status: 'FOUND',
    order: {
      order_id: order.order_id,
      order_status: order.status,
      tracking_number: order.tracking_number || null,
      carrier: order.carrier || null,
      estimated_delivery: order.estimated_delivery || null,
      current_date: currentDate,
      delivery_status: deliveryStatus,
      days_overdue: daysOverdue
    }
  }
}];
